# Dev only (epic 3 entry 12): the showcase map in its review states (CS01 priority 2, CTB1 priority 3, P12 priority 1 acknowledged, PT-1 priority 2, PT-2 priority 3 acknowledged), through the project library mapstudio_showcase_seed, so the
# engineering review pack (docs/review-er27.md, e2e/tests/review.spec.mjs) renders every state on the showcase map.
# Showcase demo tags only; MapEditor only.
import java.lang

logger = system.util.getLogger('MapStudio.devlive')
out = self.view.rootContainer.getChild('stylesResult')
if not mapstudio_dev.holdsMapEditor(self.session):
	out.props.text = system.util.jsonEncode({'refused': 'The live buttons write dev tags, so they need the MapEditor role. Sign in as a map editor first.', 'ranAt': system.date.toMillis(system.date.now())})
	return
try:
	result = mapstudio_showcase_seed.review_states('alarms')
except java.lang.Throwable as ex:
	result = {'error': ex.getClass().getSimpleName() + ': ' + str(ex.getMessage())}
except Exception as ex:
	result = {'error': str(ex)}
result['action'] = 'showcase-review-alarms'
result['ranAt'] = system.date.toMillis(system.date.now())
out.props.text = system.util.jsonEncode(result)

